def _verdict_of(steps: dict[str, dict[str, Any]]) -> str:
    vs = [s["verdict"] for s in steps.values()]
    if all(v in ("dropped", "blocked") for v in vs):
        return "dropped"
    for v in ("fail", "migration-change", "ruled"):
        if v in vs:
            return v
    return "pass"


